<script setup lang="ts">
import {useParameterTransaction} from './useParameterTransaction';
import ParameterDialog from './ParameterDialog.vue';
const settingsOpen=ref(false);
import {ref,watch,onUnmounted} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;csv:string;parameters:Record<string,number>;networkParameters:Record<string,number>;branchLimit:number}>();
const input=ref('');const seed=ref(42);const samples=ref(2);const records=ref<any[]>([]);const selected=ref<any>(null);const files=ref<any[]>([]);const error=ref('');const message=ref('');const busy=ref(false);let timer:ReturnType<typeof setTimeout>|undefined;let generation=0;
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
const statuses:Record<string,string>={queued:'等待启动',running:'后台计算中',succeeded:'计算完成',failed:'计算失败',interrupted:'进程中断'};
async function refresh(){const id=props.projectId;const token=generation;if(!id)return;const data=await api('/api/native-jobs?project_id='+id);if(id!==props.projectId||token!==generation)return;records.value=data;if(selected.value){const d=data.find((r:any)=>r.id===selected.value.id);if(d)selected.value=d;if(d&&!['queued','running'].includes(d.status)){const output=await api('/api/native-jobs/'+d.id+'/files');if(id===props.projectId&&token===generation)files.value=output}}if(timer)clearTimeout(timer);if(data.some((r:any)=>['queued','running'].includes(r.status)))timer=setTimeout(()=>refresh().catch(e=>error.value=String(e)),5000)}
watch(()=>props.projectId,()=>{generation++;if(timer)clearTimeout(timer);selected.value=null;records.value=[];input.value='';files.value=[];error.value='';refresh().catch(e=>error.value=String(e))},{immediate:true});onUnmounted(()=>{generation++;if(timer)clearTimeout(timer)});
function template(){input.value=props.csv.trim().split(/\r?\n/).map((line,i)=>i?line+',-1,0':line+',event_id,wind_speed').join('\n');message.value='模板event_id=-1表示无事件；风速0m/s是占位假设，请替换为真实天气。每个事件编号必须恰好覆盖连续36小时。'}
async function upload(event:Event){const el=event.target as HTMLInputElement;const file=el.files?.[0];try{if(file){if(file.size>8000000)throw Error('CSV不能超过8MB');const id=props.projectId;const text=await file.text();if(id===props.projectId)input.value=text}}catch(e){error.value=String(e)}finally{el.value=''}}
async function submit(){commitSettings(false);busy.value=true;error.value='';const id=props.projectId;try{const p=await api('/api/projects/'+id);const d=await api('/api/native-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:id,project_revision:p.revision,csv:input.value,parameters:props.parameters,network_parameters:props.networkParameters,branch_limit_kw:props.branchLimit,seed:seed.value,event_samples:samples.value})});if(id===props.projectId){selected.value=d;await refresh()}}catch(e){if(id===props.projectId)error.value=String(e)}finally{busy.value=false}}
async function inspect(record:any){const id=props.projectId;const token=generation;selected.value=record;files.value=[];const output=await api('/api/native-jobs/'+record.id+'/files');if(id===props.projectId&&token===generation&&selected.value?.id===record.id)files.value=output}
const commitSettings=useParameterTransaction(settingsOpen,{input,seed,samples});
</script>
<template><article><h3>原生年度网络流水线</h3><p>调用课题2论文下游原始入口，支持2至8760小时。后台独立进程运行，关闭页面后继续计算；一次运行一个任务。此入口不会生成或认证SC-RCRB场景。</p><p>输入必须包含timestamp、load_kw、wind_kw、pv_kw、event_id、wind_speed；风速单位m/s，事件外用-1，每个事件为连续36小时。可附加资源可用容量、逐时失效率和修复时长；详细字段见接口文档。</p><button class="settings-trigger" @click="settingsOpen=true">原生流水线参数与输入</button><ParameterDialog transactional @apply="commitSettings()" v-model:open="settingsOpen" title="原生流水线参数与输入"><div class="actions"><button @click="template" :disabled="busy">从当前时序建立扩展模板</button><label class="button">导入扩展CSV<input type="file" accept=".csv" hidden @change="upload" :disabled="busy"></label><a href="/openapi.json" target="_blank">API定义</a></div><p class="notice" v-if="message">{{message}}</p><textarea v-model="input" :disabled="busy" placeholder="timestamp,load_kw,wind_kw,pv_kw,event_id,wind_speed"></textarea><label class="field">随机种子<input type="number" v-model.number="seed" :disabled="busy"></label><label class="field">每个事件条件样本数 / 1–20<input type="number" min="1" max="20" v-model.number="samples" :disabled="busy"></label><p>沿用当前工作区资源、风光节点、电压与支路容量参数；输入和参数在任务启动时冻结。原算法采用风速条件支路测试失效率、连续修复和6/6/12/12小时事件分段，未校准区域风险；正式规划仍待接入。</p><button class="primary" @click="submit" :disabled="busy||!input||!projectId">{{busy?'正在提交…':'提交后台原生计算'}}</button><p class="error" v-if="error">{{error}}</p></ParameterDialog></article><article><h3>后台任务与原始产物</h3><button @click="refresh().catch(e=>error=String(e))">刷新任务</button><button v-for="r in records" class="record" @click="inspect(r).catch(e=>error=String(e))">{{r.created}} · {{r.hours}}小时 · {{statuses[r.status]}} · {{r.id.slice(0,8)}}</button><template v-if="selected"><p>{{selected.scope}}</p><p>状态：{{statuses[selected.status]}} · 输入摘要 {{selected.input_sha256.slice(0,16)}}</p><p v-if="['queued','running'].includes(selected.status)">页面每5秒更新状态；实际耗时取决于时域和事件样本数。完成前不会显示成功结论。</p><p v-if="selected.error" class="error">{{selected.error}}</p><div v-if="selected.result?.metrics" class="metrics"><article><span>缺供电量 / kWh</span><strong>{{selected.result.metrics.expected_energy_deficit_kwh.toFixed(2)}}</strong></article><article><span>最大功率缺额 / kW</span><strong>{{selected.result.metrics.max_power_deficit_kw.toFixed(2)}}</strong></article></div><div class="actions"><a :href="'/api/native-jobs/'+selected.id+'/input'" target="_blank">冻结输入与配置JSON</a><a v-if="!['queued','running'].includes(selected.status)" :href="'/api/native-jobs/'+selected.id+'/archive'">下载完整任务ZIP</a></div><p>原生任务与交互平衡分别归档。任务ZIP保留输入、逐时调度、交流校核、设备故障、事件分阶段、策略及配置试算等产物；数据库备份不包含这些外部产物文件，请单独下载任务ZIP。</p><div class="scroll"><table><tr><th>原始产物</th><th>大小 / 字节</th></tr><tr v-for="f in files"><td><a :href="'/api/native-jobs/'+selected.id+'/file?path='+encodeURIComponent(f.path)">{{f.path}}</a></td><td>{{f.bytes}}</td></tr></table></div></template></article></template>
<style scoped>.actions{flex-wrap:wrap;align-items:center}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}</style>
